CREATE INDEX IF NOT EXISTS "IX_CustomerSummariesWeekly_SourceFileJobId" ON "CustomerSummariesWeekly" ("SourceFileJobId");
CREATE INDEX IF NOT EXISTS "IX_CustomerSummariesWeekly_WeekStartDate" ON "CustomerSummariesWeekly" ("WeekStartDate");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CustomerSummariesWeekly_UQ_BySourceAndDimensions"
    ON "CustomerSummariesWeekly" ("SourceFileJobId", "WeekStartDate", "CustomerCode", "City", "ProductGroup", "TransactionType");

CREATE TABLE IF NOT EXISTS "CustomerSummariesMonthly" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SourceFileJobId" bigint NOT NULL,
    "MonthStartDate" timestamp with time zone NOT NULL,
    "CustomerCode" character varying(64) NOT NULL,
    "CustomerName" character varying(256) NOT NULL,
    "City" character varying(256) NOT NULL,
    "ProductGroup" character varying(128) NOT NULL,
    "TransactionType" character varying(128) NOT NULL,
    "Orders" integer NOT NULL,
    "Revenue" numeric(18,2) NOT NULL,
    "Quantity" numeric(18,3) NOT NULL,
