CREATE INDEX IF NOT EXISTS "IX_CustomerSummariesMonthly_SourceFileJobId" ON "CustomerSummariesMonthly" ("SourceFileJobId");
CREATE INDEX IF NOT EXISTS "IX_CustomerSummariesMonthly_MonthStartDate" ON "CustomerSummariesMonthly" ("MonthStartDate");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CustomerSummariesMonthly_UQ_BySourceAndDimensions"
